import type { PatenteHistorico } from './Seccion7_6Patentes';

type FilaPatenteComercial = [
  numero: string,
  fecha: string,
  fechaPublicacion: string,
  descripcion: string,
  tieneEfectosGenerales?: string,
  ultimaActualizacion?: string,
  urlPublicacion?: string,
  urlModificacion?: string
];

const crearPatentesComerciales = (
  filas: FilaPatenteComercial[],
  efectosPorDefecto = 'No'
): PatenteHistorico[] =>
  filas.map(([numero, fecha, fechaPublicacion, descripcion, tieneEfectosGenerales = efectosPorDefecto, ultimaActualizacion = 'Sin Modificaciones', urlPublicacion = '', urlModificacion = '']) => ({
    tipoNorma: 'Decretos Exentos',
    denominacion: 'Patentes y Permisos',
    nombreTitulo: 'Patente Comercial',
    numero,
    fecha,
    fechaPublicacion,
    tieneEfectosGenerales: tieneEfectosGenerales || efectosPorDefecto,
    ultimaActualizacion: ultimaActualizacion || 'Sin Modificaciones',
    descripcion,
    urlPublicacion, urlModificacion, enlacePublicacion: 'PDF',
    enlaceModificacion: 'Sin Modificaciones'
  }));

